"""Prospective source registry; declaring a source never means it was acquired."""
from __future__ import annotations

import json
from datetime import datetime, timezone
from pathlib import Path


SOURCES = [
    {"source_id":"phiusiil","name":"PhiUSIIL (UCI 967)","url":"https://archive.ics.uci.edu/dataset/967/phiusiil+phishing+url+dataset","collection":"URL/website tabular dataset and documented class-label convention","purpose":"URL-only historical baseline cohort","label_policy":"official label 1 is legitimate and 0 is phishing; CER mapping is the exact inverse (0 benign, 1 phishing)","access_gate":"retain the UCI release hash, citation and CC BY 4.0 attribution; preserve the existing local prepared CSV with its transformation manifest","time_policy":"static release/import time is not webpage capture, source availability, or first-seen time","status":"prepared_local_csv_present; official_archive_pending_acquisition"},
    {"source_id":"phishtank","name":"PhishTank","url":"https://phishtank.net/developer_info.php","collection":"verified phishing URLs, submission/verification timestamps, target brand, online state","purpose":"prospective phishing observations","label_policy":"verified records may assert phishing; pending/absent records are unknown, never benign","access_gate":"use descriptive User-Agent; register an application key for automated downloads; retain snapshot hash, retrieval time, response headers, and terms version","time_policy":"verification_time is a source event time; label_available_at is only the retained local snapshot receipt time","status":"not_acquired"},
    {"source_id":"phishingeval","name":"PhishingEval","url":"https://github.com/Fujiaoji/PhishingEval","collection":"available HTML, screenshots, URL/brand reference data, failure cases, and controlled perturbation examples where released","purpose":"content-level analysis and controlled perturbations","label_policy":"preserve release labels and split semantics; do not mix visual/content artifacts with URL-only records without a release manifest","access_gate":"pin repository commit and every selected Zenodo dataset artifact hash; verify applicable dataset license and terms before acquisition","time_policy":"dataset artifact timestamps do not establish web first-seen time unless collection/availability provenance is provided","status":"repository_acquired; Zenodo_dataset_artifacts_pending"},
    {"source_id":"common_crawl","name":"Common Crawl","url":"https://www.commoncrawl.org/get-started","collection":"WARC/WAT/WET archived responses and observed crawler links","purpose":"historical evidence and graph construction","label_policy":"archive presence is unlabeled content evidence; it is neither benign nor phishing proof","access_gate":"record crawl ID, CDX/WARC record locator, WARC digest, fetch timestamp, HTTP metadata, and applicable access/usage terms; parse locally without executing page content","time_policy":"use record-level crawl/fetch time only when preserved; a crawl date alone is not decision-time availability","status":"not_acquired"},
    {"source_id":"tranco","name":"Tranco","url":"https://tranco-list.eu/","collection":"versioned popular-domain ranking and permanent list identifier","purpose":"candidate pool for independently screened benign observations","label_policy":"ranked domains are benign candidates only; require independent screening/observation before a benign label","access_gate":"retain list ID, retrieval time, Last-Modified header, source attribution and component-provider terms","time_policy":"list timestamp is ranking availability, not website capture or benign-label time","status":"not_acquired"},
    {"source_id":"phishark2026","name":"PhiShark 2026","url":"https://phishark2026dataset.com/","collection":"scan metadata plus available HTML, screenshots, DNS/TLS/redirect/hosting evidence","purpose":"optional academic-access multi-layer website evidence","label_policy":"use release labels and explicit artifact availability; missing artifact remains missing","access_gate":"restricted academic/nonprofit access: manual approval, signed Data Use Agreement, non-commercial use and no redistribution; retain approval/DUA and release hashes","time_policy":"use supplied scan timestamps only with documented semantics; never infer missing capture/availability time","status":"not_acquired_restricted"},
    {"source_id":"openphish","name":"OpenPhish Community Feed","url":"https://openphish.com/phishing_feeds.html","collection":"free community feed of currently active phishing URLs","purpose":"prospective phishing observations","label_policy":"listed URLs may assert phishing at snapshot time; absence is unknown, never benign","access_gate":"review community-feed terms (non-commercial); retain snapshot hash and retrieval time; do not visit listed URLs","time_policy":"feed carries no per-URL timestamps; retrieval receipt time is the only availability time","status":"not_acquired"},
    {"source_id":"urlhaus","name":"URLhaus (abuse.ch)","url":"https://urlhaus.abuse.ch/api/","collection":"recent malware-distribution URLs with dateadded, status, threat and tags","purpose":"malicious URL observations from an independent ancestry","label_policy":"malicious-distribution label, not specifically phishing; map explicitly and never treat absence as benign","access_gate":"CC0 per abuse.ch terms; retain snapshot hash and retrieval time; do not visit listed URLs","time_policy":"dateadded is a source event time; label_available_at is the local snapshot receipt time","status":"not_acquired"},
    {"source_id":"phishing_database","name":"Phishing.Database (mitchellkrogza)","url":"https://github.com/mitchellkrogza/Phishing.Database","collection":"aggregated list of active phishing links","purpose":"prospective phishing observations","label_policy":"aggregated labels from upstream feeds; ancestry overlaps with other feeds and must be documented","access_gate":"MIT licence; pin retrieval time and file hash; do not visit listed URLs","time_policy":"no per-URL timestamps; retrieval receipt time only","status":"not_acquired"},
    {"source_id":"majestic_million","name":"Majestic Million","url":"https://majestic.com/reports/majestic-million","collection":"ranked list of top one million domains by referring subnets","purpose":"second candidate pool for independently screened benign observations","label_policy":"ranked domains are benign candidates only; require independent screening","access_gate":"CC BY 3.0 attribution; retain retrieval time and hash","time_policy":"list retrieval time is ranking availability, not website capture or benign-label time","status":"not_acquired"},
    {"source_id":"umbrella","name":"Cisco Umbrella Popularity List","url":"https://umbrella.cisco.com/blog/cisco-umbrella-1-million","collection":"ranked list of top one million domains by DNS traffic","purpose":"third candidate pool for independently screened benign observations","label_policy":"ranked domains are benign candidates only; require independent screening","access_gate":"retain retrieval time, hash and Cisco terms reference","time_policy":"list retrieval time is ranking availability, not website capture or benign-label time","status":"not_acquired"},
]


def write_source_registry(json_path: str="data/source_registry.json", markdown_path: str="docs/SOURCE_ACQUISITION_REGISTRY.md") -> dict:
    generated=datetime.now(timezone.utc).replace(microsecond=0).isoformat().replace("+00:00","Z")
    payload={"registry_version":"1.0","generated_at":generated,"sources":SOURCES,"global_rules":["A registry entry is not an acquired dataset.","No live crawling, form submission, content execution, or contact with observed targets.","Every acquired snapshot needs immutable bytes, SHA-256, receipt time, source/release identifier, and access-terms record.","Feeds and popularity lists are not benign labels by absence or rank.","Independent-source ancestry must be documented before robustness claims."]}
    p=Path(json_path);p.parent.mkdir(parents=True,exist_ok=True);p.write_text(json.dumps(payload,indent=2)+"\n",encoding="utf-8")
    rows=["# Source acquisition registry","","All entries are **not acquired**. They are controlled intake specifications, not evidence or permission to fetch.","", "| Source | What to collect | Why | Intake gate |", "| --- | --- | --- | --- |"]
    for s in SOURCES: rows.append(f"| [{s['name']}]({s['url']}) | {s['collection']} | {s['purpose']} | {s['access_gate']} |")
    rows.extend(["", "## Common rules", "", *[f"- {x}" for x in payload["global_rules"]]])
    m=Path(markdown_path);m.parent.mkdir(parents=True,exist_ok=True);m.write_text("\n".join(rows)+"\n",encoding="utf-8")
    return {"json":str(p),"markdown":str(m),"sources":len(SOURCES),"acquired":0}
